        amplitude = 1.0
        for k in range(self.max_iter):
            # Main fractal pattern
            for i in range(self.dim):
                interference += amplitude * np.cos(2**k * np.pi * x[i])

            # Cross-dimensional coupling term
            if self.dim > 1:
                coupling_term = 0.0
                for i in range(self.dim):
                    for j in range(i+1, self.dim):
                        coupling_term += np.cos(2**k * np.pi * (x[i] + x[j]))
                interference += self.coupling_strength * amplitude * coupling_term

            amplitude *= 0.5  # Reduce amplitude for finer details
        return interference

    def f(self, x):
        # Base quadratic bowl
        sphere_term = np.sum(x**2)

        # Fractal interference pattern
        fractal_term = self._fractal_interference(x)

        return sphere_term + fractal_term
